import torch

# _ops is generated by the build: `ops` holds this kernel's Torch ops, and
# add_op_namespace_prefix() gives an op's name in the kernel's own namespace.
from ._ops import add_op_namespace_prefix, ops


# A fake (meta) implementation, so the op works under torch.compile.
@torch.library.register_fake(add_op_namespace_prefix("scale"))
def _scale_fake(out: torch.Tensor, input: torch.Tensor, factor: float) -> None:
    return None


def scale(
    x: torch.Tensor, factor: float, out: torch.Tensor | None = None
) -> torch.Tensor:
    """Return x * factor (float32), computed by a HIP kernel."""
    if out is None:
        out = torch.empty_like(x)
    ops.scale(out, x.contiguous(), factor)
    return out


__all__ = ["scale"]
